results = []

def unlock(page):
    b = page.locator('[data-testid="mx-lock"]')
    if b.count() and 'Đã khóa' in b.inner_text() and not b.is_disabled():
        b.click(); page.wait_for_timeout(150)


def check(name, cond, detail=''):
    results.append((name, bool(cond), detail))
    print(('PASS ' if cond else 'FAIL ') + name + (f' — {detail}' if detail and not cond else ''))

def fresh(p, width=1366, height=900, scheme='light', storage=None, live=None):
    ctx = p.new_context(viewport={'width': width, 'height': height}, color_scheme=scheme, accept_downloads=True)
    page = ctx.new_page()
    page.add_init_script(live or 'window.__AC_CLOCK_OFF = true')
    errs = []
    page.on('pageerror', lambda e: errs.append(str(e)))
    page.on('console', lambda m: errs.append(m.text) if m.type == 'error' and 'fonts.g' not in m.text and 'ERR_' not in m.text else None)
    if storage is not None:
        page.add_init_script(f"localStorage.setItem('autocontent.state', {json.dumps(storage)})")
    page.goto(URL)
    page.wait_for_timeout(250)
    return ctx, page, errs

def no_hscroll(page):
    return page.evaluate('document.documentElement.scrollWidth <= window.innerWidth + 1')

def click_nav(page, label):
    page.locator(f'#nav-side button:has-text("{label}"), #nav-bottom button:has-text("{label}")').locator('visible=true').first.click()


def txt(page, sel='#main'): return page.locator(sel).inner_text().replace('\n', ' ')

def genai_open(page, scope='.pv-dialog .pv-card', i=None):
    # Mở hộp thoại Gen AI (mục 10.68)
    page.locator(f'{scope} [data-x="img-genai"]' + (f'[data-i="{i}"]' if i is not None else '')).first.click(); page.wait_for_timeout(250)

def genai_close(page):
    page.locator('.dialog.wide [aria-label="Đóng"]').click(); page.wait_for_timeout(250)

def genai_go(page, desc=None, prompt=None, wait=400, close=True):
    # Điền Mô tả ảnh / prompt (nếu có) rồi bấm Tạo ảnh
    if desc is not None: page.locator('#ga-desc').fill(desc)
    if prompt is not None: page.locator('#ga-chat').fill(prompt)
    page.locator('#ga-go').click(); page.wait_for_timeout(wait)
    if close: genai_close(page)

def ed(page, x, scope='.pv-dialog .pv-card', i=None):
    # Mở công cụ sửa qua nút Edit (mục 10.41); nếu trang Edit đang mở thì bấm thẳng tab
    if page.locator('.ed-box').count() == 0:
        page.locator(f'{scope} [data-x="img-edit"]' + (f'[data-i="{i}"]' if i is not None else '')).first.click(); page.wait_for_timeout(250)
    page.locator(f'.ed-box [data-ed="{x}"]').first.click()

