    import struct, zlib, tempfile
    def mkpng(w, h):
        raw = b''.join(b'\x00' + b''.join(bytes([200, 30, 60, 255]) if (y < 10 or y > h * 0.75) else bytes([0, 0, 0, 0]) for x in range(w)) for y in range(h))
        ch = lambda t, d: struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
        return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)) + ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
    fp = os.path.join(tempfile.mkdtemp(), 'khung-cty.png'); open(fp, 'wb').write(mkpng(120, 120))
