    import struct, zlib
    def _png(w, h):
        raw = b''.join(b'\x00' + bytes((200, 120, 60)) * w for _ in range(h))
        def ch(t, d): c = struct.pack('>I', len(d)) + t + d; return c + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
        return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0)) + ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
    page.locator('.cal .slot:has-text("Bài hướng dẫn")').first.click(); page.wait_for_timeout(300)
    page.locator('.pv-dialog [data-pv="edit"]').click(); page.wait_for_timeout(300)
